        ensures
            pt.1@.id() == pt.0.id(),
            pt.1@.mem_contents() == MemContents::Uninit,
    {
        let (pcell, Tracked(pt)) = pc::PCell::new(MaybeUninit::uninit());
        (PCell(pcell), Tracked(PointsTo(pt)))
